(()=>{const priorAll=allShotReferences;allShotReferences=function(target){return priorAll(target).filter(r=>!target.pictureBindingOverrides?.[r.picture]?.removed).map((r,i)=>({...r,slot:i}));};function addReference(target){const list=allShotReferences(target);if(list.length>=9){toast('最多支持9张参考图');return;}target.picture_inputs??=JSON.parse(JSON.stringify(ShotSchema.bindings(target)));const max=Math.max(0,...target.picture_inputs.map(r=>Number((r.picture||r.tag||'').match(/\d+/)?.[0]||0)));const resource=data.characters?.[0]||data.scenes?.[0];if(!resource){toast('请先添加人物或场景素材');return;}const type=data.characters?.length?'character':'scene',picture='<Picture '+(max+1)+'>';target.picture_inputs.push({picture,tag:picture,type,ref_id:resource.id||resource.character_id||resource.scene_id});target.referenceListEdited=true;save();render();toast('已添加参考图，可选择人物、场景或上一段尾帧');}
const priorShots=shots;shots=function(){priorShots();const target=shotVideoTarget(),grid=document.querySelector('.shot-script-editor .shot-reference-grid');if(!target||!grid)return;const refs=allShotReferences(target),busy=videoBusy(target.videoJob)||(typeof videoBatchActive==='function'&&videoBatchActive());for(const [i,card]of [...grid.querySelectorAll('.shot-reference-card')].entries()){const r=refs[i];if(!r)continue;const remove=document.createElement('button');remove.type='button';remove.textContent='移除参考图';remove.disabled=busy;remove.style.cssText='margin-top:12px;color:#e8aaaa';remove.onclick=()=>{target.pictureBindingOverrides??={};const o=target.pictureBindingOverrides[r.picture]??={type:r.type,ref_id:r.ref_id};o.removed=true;o.enabled=false;target.referenceListEdited=true;save();render();};card.append(remove);}const actions=document.createElement('div');actions.style.cssText='display:flex;gap:10px;flex-wrap:wrap;margin:14px 0';const add=document.createElement('button');add.type='button';add.textContent='＋ 添加参考图（'+refs.length+'/9）';add.disabled=busy||refs.length>=9;add.onclick=()=>addReference(target);actions.append(add);const removed=Object.entries(target.pictureBindingOverrides||{}).filter(([slot,o])=>o.removed).at(-1);if(removed){const undo=document.createElement('button');undo.textContent='恢复上一张移除的参考图';undo.disabled=busy;undo.onclick=()=>{delete removed[1].removed;removed[1].enabled=true;save();render();};actions.append(undo);}grid.after(actions);};render();})();
